-- Generated by Rowlit from SQL Server. Parameters (@Name) are prompted for when you run a statement.

-- Registered customers
-- dbo.Customers: UPDATE
UPDATE dbo.Customers
SET
    Name = @Name,
    Email = @Email,
    CountryId = @CountryId
WHERE Id = @Id;

-- dbo.Orders: UPDATE
UPDATE dbo.Orders
SET
    CustomerId = @CustomerId,
    OrderDate = @OrderDate,
    Total = @Total
WHERE Id = @Id;

-- dbo.OrderLines: UPDATE
UPDATE dbo.OrderLines
SET
    Qty = @Qty
WHERE OrderId = @OrderId
  AND ProductId = @ProductId;

-- dbo.Products: UPDATE
UPDATE dbo.Products
SET
    Name = @Name,
    Price = @Price
WHERE Id = @Id;

-- dbo.Countries: UPDATE
UPDATE dbo.Countries
SET
    Name = @Name
WHERE Id = @Id;

-- Sales.Invoices: UPDATE
UPDATE Sales.Invoices
SET
    OrderId = @OrderId,
    Amount = @Amount,
    IssuedAt = @IssuedAt
WHERE Id = @Id;

-- Audit trail of things that happened
-- dbo.Events: UPDATE
UPDATE dbo.Events
SET
    OccurredAt = @OccurredAt,
    Day = @Day,
    At = @At,
    Kind = @Kind,
    Payload = @Payload,
    Snapshot = @Snapshot,
    Spec = @Spec,
    Score = @Score,
    Ratio = @Ratio,
    Flags = @Flags,
    Big = @Big,
    Price = @Price,
    IsActive = @IsActive,
    Location = @Location
WHERE EventId = @EventId;

-- dbo.Keywords: UPDATE
UPDATE dbo.Keywords
SET
    class = @class,
    type = @type,
    [select] = @select,
    Keyword = @Keyword
WHERE Id = @Id;
